import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static int span(List<Integer> shts, int start, int time) {
        int i = 1;
        while (start + i < shts.size()) {
            if (shts.get(start + i) - shts.get(start) > time)
                return i;
            ++i;
        }
        return i;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Integer> shts = new ArrayList<>();
        int qtty = scanner.nextInt();
        for (int i = 0; i < qtty; ++i) {
            int aux = scanner.nextInt();
            shts.add(aux);
        }
        int ts = scanner.nextInt();
        Collections.sort(shts);
        int maxspan = 0;
        for (int i = 0; i < shts.size(); ++i) {
            int aux = span(shts, i, ts);
            if (maxspan < aux)
                maxspan = aux;
        }
        System.out.println(maxspan);
        scanner.close();
    }
}
